import java.util.*;
import java.util.function.Consumer;

public class MessageQueue {
    private final Map<String, List<Consumer<String>>> subscribers = new HashMap<>();
    private final Map<String, List<String>> deadLetterQueue = new HashMap<>();

    public void subscribe(String topic, Consumer<String> handler) {
        subscribers.computeIfAbsent(topic, k -> new ArrayList<>()).add(handler);
    }

    public void publish(String topic, String message) {
        for (Consumer<String> handler : subscribers.getOrDefault(topic, List.of())) {
            try {
                handler.accept(message);
            } catch (Exception e) {
                deadLetterQueue.computeIfAbsent(topic, k -> new ArrayList<>()).add(message);
            }
        }
    }

    public List<String> getDlq(String topic) {
        return deadLetterQueue.getOrDefault(topic, List.of());
    }

    public static void main(String[] args) {
        MessageQueue mq = new MessageQueue();
        mq.subscribe("spell.cast", msg -> System.out.println("Handler1: " + msg));
        mq.subscribe("spell.cast", msg -> {
            if (msg.contains("bad")) throw new RuntimeException("Rejected: " + msg);
            System.out.println("Handler2: " + msg);
        });
        mq.publish("spell.cast", "Fireball");
        mq.publish("spell.cast", "bad-spell");
        System.out.println("DLQ: " + mq.getDlq("spell.cast"));
    }
}

