import java.util.*;
import java.util.function.Consumer;

public class ReliableQueue {
    private final Map<String, String> queue = new HashMap<>();
    private final Map<String, Integer> retryCount = new HashMap<>();
    private final List<String> dlq = new ArrayList<>();

    public void enqueue(String msgId, String payload) { queue.put(msgId, payload); }

    public void process(String msgId, Consumer<String> handler) {
        String payload = queue.get(msgId);
        if (payload == null) { System.out.println("Not found: " + msgId); return; }
        try {
            handler.accept(payload);
            System.out.println("processed: " + payload);
        } catch (Exception e) {
            int attempts = retryCount.merge(msgId, 1, Integer::sum);
            if (attempts >= 3) {
                dlq.add(msgId);
                queue.remove(msgId);
                System.out.println("Dead lettered: " + msgId);
            } else {
                System.out.println("Retry " + attempts + " for " + msgId);
            }
        }
    }

    public static void main(String[] args) {
        ReliableQueue rq = new ReliableQueue();
        rq.enqueue("msg-1", "good");
        rq.enqueue("msg-2", "fail");
        rq.process("msg-1", p -> System.out.println("ok: " + p));
        Consumer<String> badHandler = p -> { throw new RuntimeException("cannot process: " + p); };
        rq.process("msg-2", badHandler);
        rq.process("msg-2", badHandler);
        rq.process("msg-2", badHandler);
        rq.process("msg-2", badHandler); // already DLQ'd
        System.out.println("DLQ: " + rq.dlq);
    }
}
